SELECT *
FROM sys_dictionary


        and Id = #{info.id}


        and Type = #{info.type}


        and Code = #{info.code}


        and upId = #{info.upId}


        and Name like concat('%', #{info.name}, '%')


ORDER BY Type, Level

SELECT srp.RoleId AS roleId, sp.PermissionName AS permissionName FROM sys_permissions sp INNER JOIN sys_role_permission srp ON srp.PermissionId = sp.Id LEFT JOIN sys_role sr ON srp.RoleId = sr.Id AND sr.IsDeleted = false WHERE sp.IsDeleted = false
AND srp.RoleId in
#{roleId}

SELECT *
FROM sys_role
WHERE IsDeleted = false

    AND IsDefault = #{dto.defaultRole}


    AND Id in

        #{roleId}
